query:
query PaintFixture { paints { paints {
                            id
                            name
                            data {
                                layers {
                                    opacity
                                    ty {
                                        __typename
                                        ... on PaintLayerTypeSingleColor {
                                            color {
                                                r
                                                g
                                                b
                                                a
                                            }
                                        }
                                        ... on PaintLayerTypeLinearGradient {
                                            angle
                                            repeating
                                            stops {
                                                at
                                                color {
                                                    r
                                                    g
                                                    b
                                                    a
                                                }
                                            }
                                        }
                                        ... on PaintLayerTypeRadialGradient {
                                            shape
                                            repeating
                                            stops {
                                                at
                                                color {
                                                    r
                                                    g
                                                    b
                                                    a
                                                }
                                            }
                                        }
                                        ... on PaintLayerTypeImage {
                                            images {
                                                url
                                                mime
                                                width
                                                height
                                            }
                                        }
                                    }
                                }
                                shadows {
                                    offsetX
                                    offsetY
                                    blur
                                    color {
                                        r
                                        g
                                        b
                                        a
                                    }
                                }
                            }
                        } } }
